/* precache:end */

const SHELL_CACHE = `shell-${VERSION}`;
const MEDIA_CACHE = 'media-v1';

self.addEventListener('install', (event) => {
  // The app itself must all arrive (all or nothing). The guide's voice lines are best effort:
  // one failed clip must not stop the app installing - it is fetched later when first needed.
  const core = SHELL.filter((url) => !url.endsWith('.mp3'));
  const clips = SHELL.filter((url) => url.endsWith('.mp3'));
  const fresh = (url) => new Request(url, { cache: 'reload' });
  event.waitUntil(
    caches
      .open(SHELL_CACHE)
      .then((cache) => cache.addAll(core.map(fresh)).then(() => Promise.allSettled(clips.map((url) => cache.add(fresh(url))))))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('shell-') && k !== SHELL_CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  if (url.pathname.includes('/assets/audio/')) event.respondWith(cacheFirst(event));
  else if (url.pathname.includes('/assets/data/')) event.respondWith(networkFirst(req));
  else event.respondWith(shell(req));
});

async function cacheFirst(event) {
  const req = event.request;
  const hit = await caches.match(req.url); // any cache: the guide's lines live in the shell cache
  if (hit) return hit;
  const res = await fetch(req.url);
  if (res.ok && res.status === 200) {
    const copy = res.clone();
    event.waitUntil(caches.open(MEDIA_CACHE).then((cache) => cache.put(req.url, copy))); // finish saving even if the page moves on
  }
  return res;
}

/** Fresh data when the network answers quickly; the saved copy when it is slow, broken or offline. */
async function networkFirst(req) {
  const cache = await caches.open(MEDIA_CACHE);
  const cached = (await cache.match(req.url)) || (await caches.match(req, { ignoreSearch: true }));
  const net = fetch(req, { cache: 'no-cache' }).then((res) => {
    if (res.ok) cache.put(req.url, res.clone());
    return res.ok || !cached ? res : cached;
  });
  if (!cached) return net;
  return Promise.race([net.catch(() => cached), new Promise((resolve) => setTimeout(() => resolve(cached), 2500))]);
}

async function shell(req) {
  const hit = await caches.match(req, { ignoreSearch: true });
  if (hit) return hit;
  try {
    return await fetch(req);
  } catch (err) {
    if (req.mode === 'navigate') {
      const index = await caches.match('index.html');
      if (index) return index;
    }
    throw err;
  }
}
